+      ).catch(() => null);
+
+      await RunSessionEdit(handle, parentSession, {
+        path: "other/sibling.md",
+        edits: [{ oldText: "# Sibling", newText: "# Sibling Updated" }],
+      });
+
+      const parentSiblingEnvelope = await WaitForEnvelope(
