+      AssertFileChangedPayload(parentSiblingEnvelope, "other/sibling.md", handle.config.repoRoot);
+      assert.equal(await childSiblingPromise, null);
+    }
+    finally
+    {
+      parentWs.socket.close();
+      childWs.socket.close();
+    }
+  });
+});
